    ALTER TABLE departments ADD CONSTRAINT fk_departments_manager_employee_id FOREIGN KEY (manager_employee_id) REFERENCES employees(employee_id);
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'fk_employees_department_id' AND connamespace = current_schema()::regnamespace) THEN
    ALTER TABLE employees ADD CONSTRAINT fk_employees_department_id FOREIGN KEY (department_id) REFERENCES departments(department_id);
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'fk_employees_manager_employee_id' AND connamespace = current_schema()::regnamespace) THEN
    ALTER TABLE employees ADD CONSTRAINT fk_employees_manager_employee_id FOREIGN KEY (manager_employee_id) REFERENCES employees(employee_id);
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'fk_employee_shift_assignments_employee_id' AND connamespace = current_schema()::regnamespace) THEN
    ALTER TABLE employee_shift_assignments ADD CONSTRAINT fk_employee_shift_assignments_employee_id FOREIGN KEY (employee_id) REFERENCES employees(employee_id);
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'fk_employee_shift_assignments_shift_id' AND connamespace = current_schema()::regnamespace) THEN
    ALTER TABLE employee_shift_assignments ADD CONSTRAINT fk_employee_shift_assignments_shift_id FOREIGN KEY (shift_id) REFERENCES shifts(shift_id);
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'fk_leave_requests_employee_id' AND connamespace = current_schema()::regnamespace) THEN
    ALTER TABLE leave_requests ADD CONSTRAINT fk_leave_requests_employee_id FOREIGN KEY (employee_id) REFERENCES employees(employee_id);
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'fk_leave_requests_approved_by_user_id' AND connamespace = current_schema()::regnamespace) THEN
    ALTER TABLE leave_requests ADD CONSTRAINT fk_leave_requests_approved_by_user_id FOREIGN KEY (approved_by_user_id) REFERENCES users(user_id);
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'fk_leave_requests_requested_by_user_id' AND connamespace = current_schema()::regnamespace) THEN
    ALTER TABLE leave_requests ADD CONSTRAINT fk_leave_requests_requested_by_user_id FOREIGN KEY (requested_by_user_id) REFERENCES users(user_id);
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'fk_users_employee_id' AND connamespace = current_schema()::regnamespace) THEN
    ALTER TABLE users ADD CONSTRAINT fk_users_employee_id FOREIGN KEY (employee_id) REFERENCES employees(employee_id);
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'fk_import_batches_imported_by_user_id' AND connamespace = current_schema()::regnamespace) THEN
    ALTER TABLE import_batches ADD CONSTRAINT fk_import_batches_imported_by_user_id FOREIGN KEY (imported_by_user_id) REFERENCES users(user_id);
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'fk_raw_punches_batch_id' AND connamespace = current_schema()::regnamespace) THEN
    ALTER TABLE raw_punches ADD CONSTRAINT fk_raw_punches_batch_id FOREIGN KEY (batch_id) REFERENCES import_batches(batch_id);
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'fk_raw_punches_employee_id' AND connamespace = current_schema()::regnamespace) THEN
    ALTER TABLE raw_punches ADD CONSTRAINT fk_raw_punches_employee_id FOREIGN KEY (employee_id) REFERENCES employees(employee_id);
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'fk_rejected_rows_batch_id' AND connamespace = current_schema()::regnamespace) THEN
    ALTER TABLE rejected_rows ADD CONSTRAINT fk_rejected_rows_batch_id FOREIGN KEY (batch_id) REFERENCES import_batches(batch_id);
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'fk_attendance_daily_employee_id' AND connamespace = current_schema()::regnamespace) THEN
    ALTER TABLE attendance_daily ADD CONSTRAINT fk_attendance_daily_employee_id FOREIGN KEY (employee_id) REFERENCES employees(employee_id);
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'fk_attendance_daily_shift_id' AND connamespace = current_schema()::regnamespace) THEN
    ALTER TABLE attendance_daily ADD CONSTRAINT fk_attendance_daily_shift_id FOREIGN KEY (shift_id) REFERENCES shifts(shift_id);
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'fk_punch_exceptions_punch_id' AND connamespace = current_schema()::regnamespace) THEN
    ALTER TABLE punch_exceptions ADD CONSTRAINT fk_punch_exceptions_punch_id FOREIGN KEY (punch_id) REFERENCES raw_punches(punch_id);
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'fk_evaluation_weights_created_by_user_id' AND connamespace = current_schema()::regnamespace) THEN
