  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'fk_attendance_corrections_requested_by_user_id' AND connamespace = current_schema()::regnamespace) THEN
    ALTER TABLE attendance_corrections ADD CONSTRAINT fk_attendance_corrections_requested_by_user_id FOREIGN KEY (requested_by_user_id) REFERENCES users(user_id);
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'fk_attendance_corrections_decided_by_user_id' AND connamespace = current_schema()::regnamespace) THEN
    ALTER TABLE attendance_corrections ADD CONSTRAINT fk_attendance_corrections_decided_by_user_id FOREIGN KEY (decided_by_user_id) REFERENCES users(user_id);
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'fk_attendance_corrections_punch_id' AND connamespace = current_schema()::regnamespace) THEN
    ALTER TABLE attendance_corrections ADD CONSTRAINT fk_attendance_corrections_punch_id FOREIGN KEY (punch_id) REFERENCES raw_punches(punch_id);
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'fk_audit_log_user_id' AND connamespace = current_schema()::regnamespace) THEN
